"""Plain-language parent app articles and their text-only companion."""
import json
from pathlib import Path
HERE=Path(__file__).resolve().parent
articles={}
def step(title,text,image,note='',**kw):
    return dict(title=title,text=text,image=image,alt=kw.pop('alt',title+'。説明用の名前と日付で表示した画面。'),note=note,**kw)
def states(prefix,items):
    return dict(imagePrefix=prefix,states=[[key,label] for key,label,_ in items],stateNotes={key:note for key,_,note in items})
def article(id,title,summary,before,steps,checks,faq,related,keywords):
    articles[id]=dict(audience='parents',section='app',title=title,summary=summary,before=before,chapter=1,role='保護者の方',tag='保護者アプリ',imagePrefix='app',keywords=keywords,steps=steps,checks=checks,faq=faq,relatedArticles=related,source='parent-app-manual/',sourceLabel='保護者アプリの使い方')

article('parent-app-home','保護者アプリの画面を見る','画面の上は保護者の名前、下はお子さまの名前です。それぞれの場所を見ながら、使いたい画面を開きます。','園から案内されたアプリを開き、ログインしておきます。',[
 step('上の名前は保護者の名前です','青いところに大きく出ているのは、ログインした保護者の名前です。その下で、連絡する日付を確かめます。','app-home-date','お子さまの名前は、画面を下へ動かすと出てきます。次の手順で確認します。',focused=True,alt='ホームの上の部分。①見本はなこさんは保護者の名前。②連絡する日付。③日付を変更。',calls=['「見本 はなこ さん」は保護者の名前です。','別の日にする場合は、日付を選びます。','日付を選び直したら、「日付を変更」を押します。']),
 step('お子さまの名前から、連絡の画面を開きます','画面を下へ動かし、「園児ごとの連絡・申請」を探します。ここにある、お子さまの名前を確かめてください。','app-home-child','兄弟姉妹がいるときは、連絡するお子さまの欄を使います。すでに連絡を送った日は「日次連絡を編集」と表示されます。',focused=True,alt='園児ごとの連絡・申請の部分。①見本あおいはお子さまの名前。②日次連絡を入力。③お迎え予定を登録・変更。',calls=['「見本 あおい」はお子さまの名前です。','体調や欠席を伝えるときは、「日次連絡を入力」を押します。','お迎え予定だけを入れる・変えるときは、「お迎え予定を登録・変更」を押します。']),
 step('ホームの「未読・未回答」を押します','ホームにある「未読・未回答」の欄を押します。「詳細を見る →」も同じ入口です。','app-home-unread','まだ読んでいないお知らせや、答えていないアンケートの一覧が開きます。',focused=True,alt='ホームの未読・未回答の欄。押す前の画面。',calls=['この欄を押してください。']),
 step('一覧から、読みたいものを押します','「未読・未回答」の一覧が開きました。お知らせやアンケートの名前を押してください。','app-home-updates','出欠確認のお願いが届いているときも、この一覧に出ます。',focused=True,alt='未読・未回答を押した後の一覧。①お知らせ、②未回答のアンケート。',calls=['まだ読んでいないお知らせです。','まだ答えていないアンケートです。']),
 step('ほかの画面は「メニュー」から開きます','画面の上の「メニュー」を押すと、使える画面の名前が出ます。開きたいものを押してください。','app-home-menu','「登録情報」は、自分のメール・電話・住所・勤務先を直して保存する画面です。「子ども情報変更申請」は、お子さまの情報の変更を園へ申請する画面です。',focused=True,alt='ホーム上部のメニューを開いた状態。①メニュー、②開いた項目の一覧。',calls=['「メニュー」を押して開いたところです。','この一覧から「日次連絡履歴」「お知らせ」「アンケート」などを選びます。'])
],['上の保護者名と、下のお子さまの名前を見分けられました。','連絡する日付と、使いたい画面の入口が分かりました。'],[
 ['お子さまの名前がありません','「ひもづく園児がまだありません。」と出たら、園に伝えてください。別の人の名前が出たときも、そのまま入力せず園に確認してください。'],
 ['ここで「出席」にしたら、登園の受付も終わりますか','終わりません。アプリからの連絡と、園の受付画面での登園・降園の操作は別です。園に着いたら、受付画面も操作してください。']
],['parent-app-contact','parent-app-absence','parent-app-pickup'],'保護者 アプリ ホーム メニュー 画面 日付 名前 登録情報 通知設定 パスワード')

article('parent-app-contact','朝の体調や連絡を送る','朝の体温や、おうちでの様子を園へ伝えます。画面では「日次連絡」と呼びます。','体温を測り、お子さまの様子を確かめておきます。',[
 step('お子さまの「日次連絡を入力」を押します','①の日付を確かめ、画面を下へ動かします。②のお子さまの名前を確かめ、③「日次連絡を入力」を押してください。','app-contact-entry','上に大きく出ているのは保護者の名前です。兄弟姉妹がいるときは、連絡するお子さまの欄を使います。送った内容を直すときは「日次連絡を編集」を押します。',focused=True,alt='保護者ホーム。①連絡する日付、②お子さまの名前、③日次連絡を入力ボタン。',calls=['連絡する日付です。別の日にする場合は、日付を選び直して「日付を変更」を押します。','連絡するお子さまの名前です。','「日次連絡を入力」を押すと、体調や連絡を書く画面が開きます。']),
 step('「出席」を選びます','園に行く日は「出席」を選びます。その下で、お迎えの時間、来る人、補食が必要かを入れられます。','app-contact-top','まだ分からないお迎え予定は、後から入れられます。お休みする日は「欠席」の手順を見てください。'),
 step('体温や、おうちでの様子を入れます','下へ進み、体温、寝た時刻、起きた時刻、朝食、うんちの様子などを入れます。続けて、機嫌、咳、鼻水、飲んだ薬を入れます。','app-contact-care','「性状」は、うんちの硬さや状態です。画面にある選択肢から、合うものを選びます。'),
 step('伝えたいことを書いて「保存する」を押します','「体調メモ」や「園への連絡事項」に、必要なことを書きます。下まで確かめたら「保存する」を押してください。','app-contact-bottom','入力しただけでは、園へ届きません。「保存する」を押す前に「戻る」で離れると、変更は保存されません。'),
 step('「日次連絡を保存しました。」を確かめます','ホームに戻り、「日次連絡を保存しました。」と出たら、送信できています。お子さまの欄の内容も見てください。','app-home-saved','「出席」は、園に行く予定の連絡です。登園の受付は、園に着いてから行います。'),
 step('画面全体の見本も見られます','入力するところが分からないときは、画面全体を大きくして見てください。下の切り替えで、未入力やエラーの例も見られます。','app-contact-filled','体温の入力でエラーが出たら、数値を確かめます。出席として送れない場合は、園へ連絡してください。',**states('app-contact',[('filled','入れ終わった例','出席の日の入力例です。入力欄を下まで確認できます。'),('empty','まだ入れていない例','入力前の画面です。'),('error','エラーが出た例','体温が37.5℃以上のとき、出席として送れないことを知らせる画面です。数値を低く書き換えて送らず、園へ連絡してください。')]))
],['正しい日付・お子さまの連絡を送りました。','「日次連絡を保存しました。」を確かめました。'],[
 ['間違えて送りました','同じ日付の「日次連絡を編集」を開き、直してから、もう一度「保存する」を押します。急いで伝えたい変更は、園にも連絡してください。'],
 ['保存できたか分かりません','ホームや「日次連絡履歴」で内容を確かめます。見つからないときや、通信エラーが続くときは園に連絡してください。']
],['parent-app-absence','parent-app-history','parent-arrival'],'朝 日次連絡 出席 体調 体温 食事 睡眠 排便 薬 保存 修正')

article('parent-app-absence','お休みの連絡をする','お休みする日を選び、理由を園へ伝えます。','お子さまの名前と、お休みする日を確かめてください。',[
 step('日付を選んで、連絡の画面を開きます','①がお休みする日になっているか確かめ、画面を下へ動かします。②のお子さまの名前を確かめ、③「日次連絡を入力」を押してください。','app-contact-entry','上に大きく出ているのは保護者の名前です。兄弟姉妹がいるときは、お休みするお子さまの欄を使います。すでに連絡を送った日は「日次連絡を編集」を押します。',focused=True,alt='保護者ホーム。①お休みする日付、②お子さまの名前、③日次連絡を入力ボタン。',calls=['お休みする日付です。別の日にする場合は、日付を選び直して「日付を変更」を押します。','お休みするお子さまの名前です。','「日次連絡を入力」を押すと、出席・欠席を選ぶ画面が開きます。']),
 step('「欠席」と、お休みの理由を選びます','「欠席」を押します。家庭の用事などなら「私用」、体調が悪いときは「病欠」を選びます。','app-absence-private','画像は「私用」を選んだ例です。体調が悪いときは、その下の「病欠」を選んでください。',alt='日次連絡で「欠席」と「私用」を選んだ例。「病欠」は「私用」の下にあります。'),
 step('内容を入れて「保存する」を押します','「病欠」のときは「現在の体温」と「症状」を入れます。医師から診断名を聞いているときは、その内容も入れます。「私用」のときは、必要があれば「備考」に理由を書きます。どちらも、最後に下の「保存する」を押してください。','app-absence-sick','入力しただけでは、園へ届きません。「保存する」を押してから、次の手順で確認します。',**states('app-absence',[('sick','病欠の例','「病欠」を選び、体温と症状を入れた例です。一番下に「保存する」があります。'),('private','私用休みの例','「私用」を選び、「備考」に理由を書いた例です。体温や症状の欄は出ません。一番下の「保存する」を押します。'),('error','入れ忘れがある例','体温を入れずに保存しようとした例です。上の案内を読み、体温と症状を入れて、もう一度「保存する」を押します。')])),
 step('保存できたことを確かめます','「日次連絡を保存しました。」と出たら、送信できています。ホームのお子さまの欄に、選んだ理由が出ているか見てください。','app-home-absence','画面の「病欠」は、今回の例です。私用で送った日は、その理由が表示されます。')
],['お休みする日と理由を確かめました。','「日次連絡を保存しました。」を確かめました。'],[
 ['欠席から出席に変わりました','同じ日付の「日次連絡を編集」を開き、「出席」を選び直して保存します。園にも変更を伝えてください。'],
 ['アプリから送れません','園へ電話などで連絡してください。受付時間や連絡方法は、園の案内に従ってください。']
],['parent-app-contact','parent-app-history'],'欠席 お休み 私用 病欠 発熱 症状 理由')

article('parent-app-pickup','お迎えの予定を入れる・変える','お迎えの時間や、来る人が変わるときに使います。登園する前にも入力できます。','予定を変える日と、お子さまの名前を確かめてください。',[
 step('「お迎え予定を登録・変更」を押します','①の日付を確かめ、画面を下へ動かします。②のお子さまの名前を確かめ、③「お迎え予定を登録・変更」を押してください。','app-pickup-entry','上に大きく出ているのは保護者の名前です。兄弟姉妹がいるときは、予定を入れるお子さまの欄を使います。',focused=True,alt='保護者ホーム。①予定を入れる日付、②お子さまの名前、③お迎え予定を登録・変更ボタン。',calls=['予定を入れる日付です。別の日にする場合は、日付を選び直して「日付を変更」を押します。','お迎えの予定を入れるお子さまの名前です。','「お迎え予定を登録・変更」を押すと、時間や来る人を選ぶ画面が開きます。']),
 step('時間・来る人・補食を選びます','お迎えの時刻、来る人、補食が必要かを選びます。「補食」は、夕方に食べる軽い食事です。園の案内に合わせて選んでください。','app-pickup-filled','時刻の選択肢が見つからないときは、ほかの時刻を開きます。「その他」の人を選んだときは、どなたが来るかも書きます。',**states('app-pickup',[('filled','入れ終わった例','16時30分、母、補食は不要を選んだ例です。'),('empty','まだ入れていない例','最初の画面です。'),('partial','途中まで入れた例','16時を選んだ途中の画面です。分や来る人も選んでください。'),('error','入れ忘れがある例','赤い案内が出ているところを選び直します。')])),
 step('「予定を保存」を押します','下の「予定を保存」を押すと、ホームへ戻ります。','app-pickup-filled','「ホームへ戻る」だけを押すと、今回の変更は保存されません。'),
 step('もう一度開いて、予定を確かめます','同じ日付の「お迎え予定を登録・変更」をもう一度開きます。入れた時間・来る人・補食の選択が残っているか見てください。','app-pickup-filled','予定の保存だけでは、登園・降園の受付はされません。園の受付画面でも操作してください。')
],['正しい日付・お子さまの予定を保存しました。','もう一度開いて、予定が残っていることを確かめました。'],[
 ['予定を変えられません','過去の日や、すでに降園した日は変更できません。今日の予定が変えられないときは、園に連絡してください。'],
 ['ほかの人が変更したという案内が出ました','ホームから開き直し、今の予定を確かめてから入れ直します。急なお迎えの変更は園にも連絡してください。']
],['parent-app-contact','parent-arrival','parent-departure'],'お迎え 変更 時間 時刻 人 補食 予定 保存')

article('parent-app-notices','園からのお知らせを読む','まだ読んでいないお知らせや、出欠確認のお願いを見ます。','ホームの「未読・未回答」から始めます。',[
 step('「未読・未回答」を開きます','ホームの「未読・未回答」を押します。読みたいお知らせの名前を押してください。','app-attention','以前のお知らせは「メニュー」の「お知らせ」から見られます。'),
 step('内容と、添付ファイルを見ます','お知らせを下まで読みます。ファイルが付いているときは「表示」を押すと開けます。手元に残したいときは「ダウンロード」を押します。','app-notice','ファイルが開かないときは、園に伝えてください。'),
 step('読んだお知らせを、あとから探せます','「一覧へ戻る」を押すと、お知らせの一覧に戻ります。読んだものには「既読」と表示されます。','app-notices','この見本は、開いた後の「既読」です。お知らせを開くと、読んだことが記録されます。'),
 step('出欠確認が来たら、連絡の画面へ進みます','「本日の出欠確認のお願い」が来たら、内容を読みます。「出席・欠席を連絡する」を押し、連絡を入力して保存してください。','app-notification','お知らせを読んだだけでは、出席・欠席の連絡は送られません。')
],['お知らせの内容と、必要なファイルを見ました。','出欠確認があった場合は、連絡を入力して保存しました。'],[
 ['数字が残っています','ほかの未読のお知らせや、未回答のアンケートがないか見てください。アンケートは開くだけでは回答済みになりません。'],
 ['通知が来なくても、お知らせは見られますか','はい。アプリを開いて「未読・未回答」や「お知らせ」を見てください。通知が来ないときも、ここから確認できます。']
],['parent-app-survey','parent-app-contact','parent-app-absence'],'お知らせ 未読 既読 未回答 添付 PDF 出欠確認 通知')

article('parent-app-survey','アンケートに答える','園から届いた質問に答えます。最後に「回答する」を押してください。','「メニュー」から「アンケート」を開きます。',[
 step('答えるアンケートを選びます','名前と期限を見て「回答する」を押します。お子さまごとのアンケートでは、答えるお子さまの名前も確かめます。','app-surveys','「子ども単位」はお子さま1人ずつ、「世帯単位」はご家庭で1つの回答です。'),
 step('質問に答えます','選択肢を押したり、文字を書いたりします。「*」が付いた質問は、必ず答えてください。','app-survey-filled','質問の内容や選び方は、アンケートごとに変わります。',**states('app-survey',[('filled','答えを入れた例','希望日を選び、園へ伝えたいことを書いた例です。'),('empty','まだ答えていない例','回答前の画面です。'),('error','答え忘れがある例','上の案内を読み、答えていない質問を確認します。')])),
 step('下の「回答する」を押します','答えを確かめてから、画面の下の「回答する」を押します。','app-survey-filled','「戻る」だけを押すと、今回の答えは保存されません。'),
 step('「回答しました。」を確かめます','一覧に戻り、「回答しました。」と出たら終わりです。「回答済み」になっていることも見てください。','app-survey-done','兄弟姉妹それぞれに回答が必要なときは、ほかのお子さまについても答えます。')
],['答えるお子さま・ご家庭を確かめました。','「回答しました。」と「回答済み」を確かめました。'],[
 ['答えを直したいです','一覧の「回答を編集」を押します。直した後、もう一度「回答する」を押してください。開けないときは園に相談してください。'],
 ['「要確認」と出て答えられません','園に、表示されている内容を伝えてください。別のアカウントを作り直す必要はありません。']
],['parent-app-notices','parent-app-home'],'アンケート 回答 質問 編集 必須 期限 回答済み')

article('parent-app-history','前の連絡や、園からの返信を見る','送った内容と、園からの返信をあとから見られます。','「メニュー」から「日次連絡履歴」を開きます。',[
 step('「日次連絡履歴」を開きます','画面の上の「メニュー」を押し、「日次連絡履歴」を選びます。ホームの「履歴を見る」からも開けます。','app-menu'),
 step('日付と名前を見て、内容を読みます','連絡は新しいものから並びます。お子さまの名前と日付を見て、探している連絡を読んでください。返信があると「園からの連絡」も出ます。','app-history'),
 step('返信を読み、必要なら連絡を直します','「内容を編集」を押すと、その日の連絡を開けます。上に「園からの返信」があれば読みます。自分が送った内容を直すときは、下へ進んで直し、「保存する」を押します。','app-reply','返信を読むだけなら、保存し直す必要はありません。ホームに「返信あり」と出たときは、そこからも読めます。')
],['確認したい日付・お子さまの連絡を見ました。','返信がある場合は、その内容を読みました。'],[
 ['まだ返信がありません','園が返信を公開すると表示されます。急いで確認したいことは、園へ直接連絡してください。'],
 ['送ったはずの連絡がありません','日付とお子さまの名前を確かめます。見つからないときは、保存できていない可能性があります。園に確認してください。']
],['parent-app-contact','parent-app-notices'],'履歴 日次連絡 返信 過去 修正 園からの連絡')

from notification_content import add_notifications
add_notifications(articles, article, step)
from audit_review_content import apply_review
apply_review(articles)

(HERE/'parent_app_articles.json').write_text(json.dumps(articles,ensure_ascii=False,indent=2)+'\n',encoding='utf-8')
doc=['# 保護者アプリの使い方','', '[スクショ付きの手順を開く](manual-guide-preview/index.html#parent-app){ .md-button .md-button--primary }','', 'スマートフォンなどで、園への連絡やお知らせの確認をする方法です。短い手順ごとに読めます。','', '登園・降園の受付は、[園にある受付画面](parent-attendance-manual.md)で行います。アプリで「出席」を選んだり、お迎え予定を保存したりするだけでは、登園・降園の受付は終わりません。','']
for id,a in articles.items():
    doc += ['## '+a['title'],'',a['summary'],'','[この手順をスクショ付きで読む](manual-guide-preview/index.html#article/'+id+')','',a['before'],'']
    for i,s in enumerate(a['steps'],1):
        if '画面全体の見本' in s['title']:continue
        doc += [f"{i}. **{s['title']}** {s['text']}"+(' '+' '.join(s['calls']) if s.get('calls') else '')+((' '+s['note']) if s['note'] else '')]
    doc += ['', '**困ったとき**','']
    for q,ans in a['faq']:doc += ['- **'+q+'** '+ans]
    if a.get('references'):
        doc += ['',a['sourceNote'],'', '公式の案内：'+ ' · '.join(f'[{label}]({url})' for label,url in a['references']), '']
    doc += ['']

doc += ['## 画面について','', '2026年11月3日に確認した配備版をもとに、説明用の名前や日付で撮影しています。このマニュアルの画像から、園へ連絡を送ることはできません。園の画面と違うときや、操作が分からないときは、園の職員に聞いてください。','', 'ホームの見方と毎日の連絡に加え、Android・iPhoneの通知設定を案内しています。スマートフォン側の画像は公式案内をもとにした操作の図で、実機のスクリーンショットではありません。子ども情報変更申請・登録情報・パスワード変更は入口を案内し、詳しい手順は今後確認して追加します。','', '[作成・確認の記録](spec-decisions.md#sd-019) · [ホーム案内の修正](spec-decisions.md#sd-020) · [日次連絡の入口の修正](spec-decisions.md#sd-021) · [お休みの手順の修正](spec-decisions.md#sd-022) · [お迎えの手順の修正](spec-decisions.md#sd-023) · [通知設定の追加](spec-decisions.md#sd-024) · [画像と説明の訂正](spec-decisions.md#sd-025) · [保護者用のホーム](manual-guide-preview/index.html#parents)','']
